window.LuminaAdminData=async({defaultMode='live',simulationAvailable=false,revenue,root,kind,api,L,e,money,stateLabel,orderLink,invoiceLink,onRows,onReview})=>{
 const F=globalThis.LuminaOrderFormat,locale=document.documentElement.lang;
 const date=v=>v?new Date(v).toLocaleDateString(document.documentElement.lang):'',badge=s=>`<span class="admin-badge state-${e(s)}">${e(stateLabel(s))}</span>`;
 const definitions={
 orders:{title:L('Orders','Commandes'),statuses:['pending_payment','awaiting_verification','paid','rejected','refunded'],columns:[['id',L('Order','Commande'),orderLink],['customer_name',L('Customer','Client'),r=>`<strong>${e(r.customer_name)}</strong><small>${e(r.customer_email)}</small>`],['plan_name',L('Plan','Forfait'),r=>`${e(r.plan_name)}<small>${e(F.formatDuration(r,locale))} · ${e(F.formatScreens(r.screens,locale))}</small>`],['order_status',L('Order Status','État de la commande'),r=>badge(F.displayStatus(r))],['payment_status',L('Payment Status','État du paiement'),r=>r.payment_status==='pending_payment'?`<span class="admin-badge state-pending_payment">${L('Pending','En attente')}</span>`:badge(r.payment_status)],['total_cents',L('Amount','Montant'),r=>money(r.total_cents)],['created_at',L('Created','Créée'),r=>date(r.created_at)]]},
 payments:{title:L('Payments','Paiements'),statuses:['pending','verified','rejected'],columns:[[null,L('Order / customer','Commande / client'),r=>`${e(r.order_reference||'')}<small>${e(r.customer_name||'')} · ${e(r.customer_email||'')}</small>`],[null,L('Receiving account','Compte destinataire'),r=>`${e(r.mode==='test'?L('TEST ONLY · Non-payable','TEST UNIQUEMENT · Non payable'):(r.receiving_account?.nickname||L('Legacy account not recorded','Ancien compte non enregistré')))}<small>${e(r.receiving_account?.email||(r.receiving_account?.address?r.receiving_account.address.slice(0,8)+'…'+r.receiving_account.address.slice(-6):''))}</small>`],['created_at',L('Received','Reçue'),r=>date(r.created_at)],['plan_name',L('Plan','Forfait'),r=>`${e(r.plan_name)}<small>${e(F.formatDuration(r,locale))}</small>`],['method',L('Method / reference','Mode / référence'),r=>`<strong>${e(r.method)}</strong><small class="admin-reference" title="${e(r.confirmation)}">${e(r.confirmation)}</small>`],['total_cents',L('Amount','Montant'),r=>money(r.total_cents)],['status',L('Status','État'),r=>badge(r.status)], [null,L('Actions','Actions'),r=>r.status==='pending'?`<button class="btn small" data-review-claim="${e(r.id)}">${L('Review','Vérifier')}</button>`:e(r.mode==='test'?L('DEMO / TEST','DÉMO / TEST'):stateLabel(r.mode))]]},
 invoices:{title:L('Invoices','Factures'),statuses:['issued','draft','paid','credited'],columns:[['id',L('Invoice','Facture'),invoiceLink],['kind',L('Type','Type'),r=>e(stateLabel(r.kind))],['status',L('Status','État'),r=>badge(r.status)],['amount_cents',L('Amount','Montant'),r=>money(r.amount_cents)],['created_at',L('Issued','Émise'),r=>date(r.created_at)], [null,L('Delivery','Envoi'),r=>r.mode==='test'?L('Demo: email disabled','Démo : courriel désactivé'):`<button class="btn small" data-send-invoice="${r.id}">${L('Email PDF','Envoyer le PDF')}</button>`]]},
 customers:{title:L('Customers','Clients'),statuses:[],columns:[['name',L('Customer','Client'),r=>e(r.name)],['email',L('Email','Courriel'),r=>e(r.email)],['orders',L('Orders','Commandes'),r=>r.orders],['ordered_cents',L('Order value','Valeur des commandes'),r=>money(r.ordered_cents)],['created_at',L('Last order','Dernière commande'),r=>date(r.created_at)]]},
 subscriptions:{title:L('Subscriptions','Abonnements'),statuses:['active','expired','cancelled'],columns:[['name',L('Customer','Client'),r=>`<strong>${e(r.name)}</strong><small>${e(r.email)}</small>`],['plan_name',L('Plan','Forfait'),r=>`${e(r.plan_name)}${r.mode==='test'?'<small>DEMO / TEST</small>':''}`],['effective_status',L('Status','État'),r=>badge(r.effective_status)],['activated_at',L('Activated','Activé'),r=>date(r.activated_at)],['expires_at',L('Expires','Expire'),r=>date(r.expires_at)], [null,L('Order','Commande'),orderLink]]},
 };
 const d=definitions[kind];let offset=0,limit=10,sort=d.columns.find(c=>c[0])[0],direction='desc',search='',filter=new URLSearchParams(location.search).get('status')||'',mode=(['live','test'].includes(new URLSearchParams(location.search).get('mode'))?new URLSearchParams(location.search).get('mode'):defaultMode),orderStatus=new URLSearchParams(location.search).get('order_status')||'',version=0,timer,current=[];
 root.innerHTML=`${revenue?`<div class="commerce-box"><h2>${revenue.mode==='test'?L('Demo Live Revenue','Revenus démo'):L('Verified revenue','Revenus vérifiés')}</h2><strong>${money(revenue.cents)} CAD</strong></div>`:''}<section class="admin-data-panel"><div class="admin-panel-heading"><div class="actions"><button class="btn small" data-export>${L('Export page CSV','Exporter la page CSV')}</button><button class="btn small" data-refresh>${L('Refresh','Actualiser')}</button></div></div><div class="admin-table-toolbar"><label class="admin-search"><span>${L('Search records','Rechercher')}</span><input type="search" data-search placeholder="${L('Search by name, email or reference…','Nom, courriel ou référence…')}"></label>${d.statuses.length?`<label>${kind==='orders'?L('Payment Status','État du paiement'):L('Status','État')}<select data-status><option value="">${L('All statuses','Tous les états')}</option>${d.statuses.map(s=>`<option value="${s}">${e(kind==='orders'&&s==='pending_payment'?L('Pending','En attente'):stateLabel(s))}</option>`).join('')}</select></label>`:''}<label>${L('Rows per page','Lignes par page')}<select data-limit>${[10,25,50,100].map(n=>`<option>${n}</option>`).join('')}</select></label><button class="admin-clear" data-clear>${L('Reset','Réinitialiser')}</button></div><p data-table-error role="alert"></p><div class="table-wrap admin-data-wrap" data-results aria-busy="true"></div><div class="admin-table-footer"><span data-count role="status" aria-live="polite"></span><div><button class="btn small" data-prev>${L('Previous','Précédent')}</button><span data-page></span><button class="btn small" data-next>${L('Next','Suivant')}</button></div></div></section><div data-review-area></div>`;
 const $=s=>root.querySelector(s);if(simulationAvailable){const label=document.createElement('label');label.textContent=L('Financial data','Données financières');const select=document.createElement('select');select.dataset.mode='';for(const [value,text]of [['live',L('Real','Réel')],['test',L('Demo / test','Démo / test')]]){const option=document.createElement('option');option.value=value;option.textContent=text;select.append(option);}select.value=mode;label.append(select);$('.admin-table-toolbar').prepend(label);select.onchange=()=>{const url=new URL(location.href);url.searchParams.set('mode',select.value);location.href=url;};}if(!d.statuses.includes(filter))filter='';if(!['live','test'].includes(mode))mode='';if($('[data-status]'))$('[data-status]').value=filter;if(kind==='orders'){if(!['pending_payment','processing','fulfilled','cancelled','refunded'].includes(orderStatus))orderStatus='';const statusLabel=document.createElement('label');statusLabel.textContent=L('Order Status','État de la commande');const statusSelect=document.createElement('select');statusSelect.dataset.orderStatus='';for(const value of ['', 'pending_payment','processing','fulfilled','cancelled','refunded']){const option=document.createElement('option');option.value=value;option.textContent=value?stateLabel(value):L('All order statuses','Tous les états de commande');statusSelect.append(option);}statusLabel.append(statusSelect);$('.admin-table-toolbar').insertBefore(statusLabel,$('[data-clear]'));statusSelect.value=orderStatus;statusSelect.addEventListener('change',()=>{orderStatus=statusSelect.value;offset=0;draw();});}

 async function draw(){const ticket=++version;$('[data-results]').setAttribute('aria-busy','true');$('[data-table-error]').textContent='';try{const result=await api('table?'+new URLSearchParams({kind,q:search,status:filter,order_status:orderStatus,mode,offset,limit,sort,direction}));if(ticket!==version)return;current=result.rows;if(offset&&offset>=result.total){offset=Math.max(0,Math.floor((result.total-1)/limit)*limit);return draw();}
 $('[data-results]').innerHTML=`<table class="admin-data-table"><caption class="sr-only">${d.title}</caption><thead><tr>${d.columns.map(([field,label])=>`<th scope="col"${field?` aria-sort="${field===sort?(direction==='asc'?'ascending':'descending'):'none'}"`:''}>${field?`<button data-sort="${field}">${e(label)}<span aria-hidden="true">${field===sort?(direction==='asc'?'↑':'↓'):'↕'}</span></button>`:e(label)}</th>`).join('')}</tr></thead><tbody>${current.length?current.map(r=>`<tr>${d.columns.map(([, ,render])=>`<td>${render(r)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${d.columns.length}" class="admin-empty"><strong>${L('No matching records','Aucun résultat')}</strong><p>${L('Try another search or clear the filters.','Essayez une autre recherche ou effacez les filtres.')}</p></td></tr>`}</tbody></table>`;
 $('[data-count]').textContent=result.total?`${offset+1}–${offset+current.length} ${L('of','sur')} ${result.total}`:L('0 records','0 résultat');$('[data-page]').textContent=`${Math.floor(offset/limit)+1} / ${Math.max(1,Math.ceil(result.total/limit))}`;$('[data-prev]').disabled=offset===0;$('[data-next]').disabled=offset+limit>=result.total;$('[data-export]').disabled=!current.length;
 root.querySelectorAll('[data-sort]').forEach(b=>b.addEventListener('click',()=>{if(sort===b.dataset.sort)direction=direction==='asc'?'desc':'asc';else{sort=b.dataset.sort;direction='asc';}offset=0;draw();}));onRows();root.querySelectorAll('[data-review-claim]').forEach(b=>b.addEventListener('click',()=>onReview(current.find(c=>c.id===b.dataset.reviewClaim),$('[data-review-area]'))));
 }catch(error){if(ticket===version)$('[data-table-error]').textContent=error.message;}finally{if(ticket===version)$('[data-results]').setAttribute('aria-busy','false');}}
 $('[data-search]').addEventListener('input',event=>{search=event.target.value;offset=0;clearTimeout(timer);timer=setTimeout(draw,250);});$('[data-status]')?.addEventListener('change',event=>{filter=event.target.value;offset=0;draw();});$('[data-limit]').addEventListener('change',event=>{limit=Number(event.target.value);offset=0;draw();});$('[data-prev]').addEventListener('click',()=>{offset=Math.max(0,offset-limit);draw();});$('[data-next]').addEventListener('click',()=>{offset+=limit;draw();});$('[data-refresh]').addEventListener('click',draw);$('[data-clear]').addEventListener('click',()=>{search='';filter='';mode='live';orderStatus='';offset=0;if($('[data-order-status]'))$('[data-order-status]').value='';if($('[data-mode]'))$('[data-mode]').value=mode;$('[data-search]').value='';if($('[data-status]'))$('[data-status]').value='';draw();});
 $('[data-export]').addEventListener('click',()=>{const cell=value=>'"'+String(value??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';const headers=d.columns.filter(c=>c[0]),csv='\uFEFF'+headers.map(c=>cell(c[1])).join(',')+'\r\n'+current.map(row=>headers.map(([field])=>cell(row[field])).join(',')).join('\r\n'),a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='lumina-'+kind+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});await draw();return draw;
};
